-- 신조어 10개 승격 (2026-09-07, 운영자 승인). 아침 검수 세션에서 native_review_pending
-- 후보 12건 중 10건 승인, 드렁슨/진지스칸 2건은 보류.
--
-- 엄친딸: 운영자가 "에겐(남/녀)와 같은 규칙으로" 추가 지시. 에겐(271)/테토(272)가 성별
-- 파생형을 aliases로 통합한 선례를 따라 표제어는 '엄친아' 하나, '엄친딸'은 aliases에 넣었다.
-- 초안 definition/usage가 이미 5개 언어 전부에서 여성형 '엄친딸'을 명시하고 있어 본문은
-- 손대지 않았다.
--
-- 오히려 좋아: 운영자가 침착맨 유행어 여부를 물었고, draft 유지로 확정. 출처 3곳이
-- 공통으로 침착맨을 '대중화 계기'로만 꼽고 최초 발화자는 확정하지 않아 origin도 그대로 둔다.
--
-- 초안이 남긴 유보 사항(그대로 유지):
--   병맛(295)  category=slang — 어원이 '병신 같은 맛'이라 존맛탱(102)과 같은 처리. 성인 게이트 대상.
--   넘사벽(296) 일본 2ch '超えられない壁' 유입설이 나무위키에만 상세 → origin은 '알려져 있다'로 완화.
--   엄친아(297) 줄임말 최초 사용처는 출처마다 갈려 확정하지 않음.
--   안물안궁(298) 정확한 발생 연도 미확인 → '2010년대 중반'으로만 기록. 출처 4건 중 2건이 동일 매체.
--   극혐(299)  category=new-slang 유지. 사람·집단 대상 사용 시 혐오 표현이 되는 점을 usage에 명시함.
--   폼 미쳤다(300) origin에 축구 해설가 이주헌의 별명 '추멘'이 실명으로 들어간다(뉴시스 등 언론 보도 근거).
--   오히려 좋아(301) 어원 여러 설 병존, 확정하지 않음.
--   이븐하게(302) <흑백요리사> 심사평 발화자를 출처가 특정하지 않아 이름 미기재.
--   실화냐(303) 표제어는 통용도 기준 '실화냐', '이거 실화냐'/'실화임?'은 aliases.
--   나락(304)  최초 발화자 미확정. 기존 떡락(246)과 뜻이 일부 겹치나 별개 단어로 판단
--              (떡락=수치·시세 하락, 나락=평판 붕괴).
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations, aliases) values
('295', '병맛', 'Byeong-Mat', 'slang', '어이없어서 오히려 웃긴 맛', '{"de": "So absurd, dass es wieder komisch ist", "en": "So absurd it loops back around to funny", "es": "Tan absurdo que acaba dando risa", "ja": "あきれるほど不条理で逆に笑える味", "vi": "Vô lý tới mức lại thành buồn cười"}'::jsonb, '[병맏]', '[{"type": "명사", "examples": [{"de": "Dieser Webtoon ist völliger Blödsinn – warum lese ich trotzdem weiter?", "es": "Este webtoon es puro disparate… ¿por qué no puedo dejar de leerlo?", "ja": "このウェブトゥーン、マジでビョンマッなのになんで見ちゃうんだろ?", "vi": "Webtoon này nhảm thật sự mà sao mình đọc hoài vậy?", "eng": "This webtoon is total nonsense — so why can''t I stop reading it?", "kor": "이 웹툰 진짜 병맛인데 왜 계속 보게 되지?"}, {"de": "Sie haben die Werbung völlig absurd gemacht – und die Klicks sind explodiert.", "es": "Hicieron el anuncio en plan absurdo y las visitas se dispararon.", "ja": "広告をビョンマッで作ったら再生数が爆発したらしい。", "vi": "Họ làm quảng cáo theo kiểu nhảm mà lượt xem bùng nổ luôn.", "eng": "They went full absurdist with the ad and the views blew up.", "kor": "광고를 병맛으로 뽑았더니 조회수 터졌대."}], "definition": "맥락 없고 어이없는데 그래서 오히려 웃긴 특유의 코드. ''병신 같은 맛''의 준말로, 2000년대 후반 디시인사이드 카툰연재 갤러리의 이른바 ''병맛 만화''에서 굳었다. 지금은 웹툰·광고·예능까지 ''병맛 코드''라는 장르 이름처럼 쓰인다.", "definition_i18n": {"de": "Ein Humorstil, der zusammenhanglos und absurd ist – und genau deshalb komisch. Kurz für ''ein beschissener Geschmack''; entstanden Ende der 2000er rund um die absurden Webcomics des DCInside-Comicboards, heute fast ein Genrelabel für Webtoons, Werbung und Shows.", "en": "A humor style that is pointless and ridiculous, and funny precisely because of it. Short for ''a crappy taste'', it took shape in the late 2000s around the absurdist webcomics of DCInside''s cartoon board, and now works almost as a genre label for webtoons, ads and variety shows.", "es": "Un estilo de humor sin sentido y ridículo, y gracioso justo por eso. Abreviatura de ''sabor a basura'', cuajó a finales de los 2000 con los cómics absurdos del foro de viñetas de DCInside, y hoy funciona casi como etiqueta de género en webtoons, anuncios y programas.", "ja": "脈絡がなくあきれるのに、だからこそ笑える独特のコード。「病身のような味」の略で、2000年代後半のDCインサイド漫画掲示板のいわゆる「ビョンマッ漫画」で定着した。今はウェブトゥーンや広告、バラエティまで「ビョンマッコード」というジャンル名のように使われる。", "vi": "Kiểu hài không đầu không cuối, vô lý nhưng chính vì thế mà buồn cười. Rút gọn của ''vị dở hơi'', nó định hình cuối thập niên 2000 quanh các webcomic nhảm trên diễn đàn truyện tranh DCInside, giờ gần như là tên một thể loại cho webtoon, quảng cáo và show giải trí."}}]'::jsonb, '''병신 같은 맛''의 준말. 2000년대 후반 디시인사이드 카툰연재 갤러리에서 무악공고·잉위 등의 만화를 두고 쓰이던 ''병신 같은 맛''이 ''병맛''으로 줄어 굳었다. 처음에는 ''어이없는데 웃기다''는 긍정적 뉘앙스였는데, 아류작이 쏟아지며 ''성의 없다''는 부정적 뜻도 함께 생겼다.', '{"de": "Kurz für ''ein beschissener Geschmack''. Ende der 2000er benutzte das DCInside-Comicboard die volle Wendung für die Comics von Zeichnern wie Muakgonggo und Ingwi; sie wurde zu 병맛 verkürzt. Zuerst hieß es ''absurd, aber lustig'', mit der Flut an Nachahmern kam die negative Note ''lieblos'' dazu.", "en": "Short for ''a crappy taste''. In the late 2000s DCInside''s cartoon board used the full phrase about the comics of artists like Muakgonggo and Ingwi; it got clipped to 병맛 and stuck. It first meant ''ridiculous but funny'', then picked up a negative ''lazy and unfunny'' sense as imitators piled up.", "es": "Abreviatura de ''sabor a basura''. A finales de los 2000 el foro de viñetas de DCInside usaba la frase completa para los cómics de autores como Muakgonggo e Ingwi; se acortó a 병맛 y cuajó. Al principio era ''ridículo pero gracioso''; con la avalancha de imitadores ganó también el matiz negativo de ''chapucero''.", "ja": "「病身のような味」の略。2000年代後半、DCインサイドの漫画掲示板でムアク工高やインウィらの作品を指して使われた表現が「ビョンマッ」に縮まって定着した。当初は「あきれるけど面白い」という肯定的な意味だったが、模倣作が乱立して「雑で笑えない」という否定的な意味も加わった。", "vi": "Rút gọn của ''vị dở hơi''. Cuối thập niên 2000, diễn đàn truyện tranh DCInside dùng cụm đầy đủ cho tác phẩm của những tác giả như Muakgonggo, Ingwi; rồi rút thành 병맛 và giữ luôn. Ban đầu nghĩa là ''vô lý mà vui'', sau khi hàng loạt bản nhái xuất hiện thì có thêm sắc thái tiêu cực ''làm cho có''."}'::jsonb, '친구끼리 콘텐츠나 상황을 평할 때 쓴다. ''병맛 웹툰'', ''병맛 코드''처럼 장르 이름에 가깝게도 쓰이지만, 어원이 장애 비하어 ''병신''이라 공식 자리나 윗사람 앞에서는 피하는 게 좋다.', '{"de": "Unter Freunden für Inhalte oder Situationen, fast schon als Genre-Tag (''병맛-Webtoon''). Da es von 병신 stammt, einem behindertenfeindlichen Schimpfwort, in formellen Situationen und vor Älteren besser vermeiden.", "en": "Used among friends to describe content or situations, and almost as a genre tag (''병맛 webtoon''). Because it comes from 병신, an ableist slur, keep it out of formal settings and away from elders.", "es": "Se usa entre amigos para describir contenidos o situaciones, casi como etiqueta de género (''webtoon 병맛''). Como viene de 병신, un insulto capacitista, evítalo en contextos formales o ante personas mayores.", "ja": "友達同士でコンテンツや状況を評するときに使う。「ビョンマッ漫画」のようにジャンル名にも近いが、語源が障害者差別語の「病身」なので、公式の場や目上の前では避けたほうがいい。", "vi": "Dùng giữa bạn bè để nhận xét nội dung hay tình huống, gần như một nhãn thể loại (''webtoon 병맛''). Vì bắt nguồn từ 병신 - một từ miệt thị người khuyết tật - nên tránh dùng nơi trang trọng hoặc trước người lớn."}'::jsonb, array['노잼','밈','짤'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Absurdist / so-bad-it''s-good humor"}, {"lang": "🇯🇵 JA", "text": "シュールで逆に笑える味"}, {"lang": "🇨🇳 ZH", "text": "荒诞到好笑的风格"}, {"lang": "🇻🇳 VI", "text": "Kiểu hài nhảm vô lý"}, {"lang": "🇪🇸 ES", "text": "Humor absurdo"}, {"lang": "🇩🇪 DE", "text": "Absurder Humor"}]'::jsonb, array[]::text[]),
('296', '넘사벽', 'Neom-Sa-Byeok', 'new-slang', '따라잡을 수 없는 압도적 격차', '{"de": "Ein uneinholbarer Abstand", "en": "A gap too big to ever close", "es": "Una brecha imposible de salvar", "ja": "追いつけない圧倒的な差", "vi": "Khoảng cách không thể đuổi kịp"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Ihr Gesang ist einfach unerreichbar, kein Vergleich.", "es": "Cantan a un nivel inalcanzable, no hay comparación.", "ja": "あの子の歌唱力はもう越えられない壁、比較にならない。", "vi": "Giọng hát của bạn ấy là đẳng cấp không với tới, không so được.", "eng": "Their singing is just on another level — there''s no comparison.", "kor": "쟤 노래 실력은 그냥 넘사벽이야, 비교가 안 돼."}, {"de": "Der Abstand zum ersten Platz war unaufholbar, also habe ich aufgegeben.", "es": "La diferencia con el primero era abismal, así que me rendí.", "ja": "1位との点差が越えられない壁すぎて諦めた。", "vi": "Cách biệt điểm với người đứng đầu quá lớn nên mình bỏ cuộc.", "eng": "The gap to first place was unbridgeable, so I gave up.", "kor": "1등이랑 점수 차이가 넘사벽이라 포기했어."}], "definition": "''넘을 수 없는 사차원의 벽''의 준말. 실력이나 수준 차이가 너무 커서 아무리 노력해도 따라잡을 수 없는 상대나 격차를 가리킨다. 상대를 치켜세우는 칭찬으로도, 나는 못 따라간다는 체념으로도 쓴다.", "definition_i18n": {"de": "Kurz für ''die unüberwindbare vierdimensionale Mauer'' — ein Niveauunterschied, den man nie aufholt. Mal hohes Lob für die andere Seite, mal Resignation über die eigene.", "en": "Short for ''a fourth-dimensional wall you cannot climb'' — a gap in skill or level so wide that catching up is hopeless. Used both as high praise for the other side and as resignation about your own.", "es": "Abreviatura de ''el muro de cuarta dimensión que no se puede cruzar'': una diferencia de nivel tan grande que alcanzarla es imposible. Sirve como elogio para el otro y como resignación sobre uno mismo.", "ja": "「越えられない四次元の壁」の略。実力や水準の差が大きすぎて、どんなに努力しても追いつけない相手や格差を指す。相手を持ち上げる褒め言葉にも、自分は無理だという諦めにも使う。", "vi": "Viết tắt của ''bức tường chiều thứ tư không thể vượt qua'' — khoảng cách trình độ lớn tới mức có cố cũng vô vọng. Vừa là lời khen dành cho đối phương, vừa là sự buông xuôi về bản thân."}}]'::jsonb, '일본 2ch의 ''넘을 수 없는 벽(超えられない壁)''이라는 표현이 2000년대 후반 한국 인터넷 커뮤니티로 넘어오면서 ''사차원''이 붙어 ''넘을 수 없는 사차원의 벽''이 됐고, 이후 원말은 거의 쓰이지 않고 준말 ''넘사벽''만 남아 굳은 것으로 알려져 있다.', '{"de": "Die japanische 2ch-Wendung ''eine Mauer, die man nicht überwindet'' soll Ende der 2000er in koreanische Foren gelangt sein, wo ''vierdimensional'' ergänzt wurde; die Langform verschwand, übrig blieb nur 넘사벽.", "en": "The Japanese 2ch phrase ''a wall you cannot cross'' is said to have crossed into Korean forums in the late 2000s, where ''fourth-dimensional'' was tacked on; the full phrase fell out of use and only the clipped 넘사벽 survives.", "es": "Se dice que la frase japonesa de 2ch ''un muro que no se puede cruzar'' pasó a los foros coreanos a finales de los 2000, donde se le añadió ''de cuarta dimensión''; la forma larga cayó en desuso y solo sobrevive 넘사벽.", "ja": "日本の2chの「超えられない壁」が2000年代後半に韓国のネットコミュニティへ渡り、「四次元」が加わって「越えられない四次元の壁」となり、その後は元の言い方が廃れ略語の넘사벽だけが残ったとされる。", "vi": "Cụm ''bức tường không thể vượt'' trên 2ch của Nhật được cho là du nhập vào diễn đàn Hàn cuối thập niên 2000, rồi được thêm ''chiều thứ tư''; dạng đầy đủ dần biến mất, chỉ còn 넘사벽."}'::jsonb, '비교 대상 뒤에 붙여 ''넘사벽이다'', ''넘사벽 차이''처럼 쓴다. 원말 ''넘을 수 없는 사차원의 벽''은 지금 거의 안 쓰고 줄임말만 쓴다. 욕이 아니라 감탄에 가까워 일상 대화에서 무난하다.', '{"de": "Hängt man an das Verglichene: 넘사벽이다, 넘사벽 차이. Die Langform ist praktisch tot. Eher Bewunderung als Beleidigung, im Alltag also unproblematisch.", "en": "Attach it to whatever you''re comparing: 넘사벽이다, 넘사벽 차이. The full phrase is basically dead; only the clip is used. It''s closer to admiration than insult, so it''s safe in everyday talk.", "es": "Se añade a lo que comparas: 넘사벽이다, 넘사벽 차이. La forma larga ya no se usa. Es más admiración que insulto, así que vale en conversación diaria.", "ja": "比較対象の後ろに付けて「넘사벽이다」「넘사벽 차이」のように使う。元の長い言い方はほぼ使われず略語のみ。悪口ではなく感嘆に近いので日常会話でも問題ない。", "vi": "Gắn sau đối tượng so sánh: 넘사벽이다, 넘사벽 차이. Dạng đầy đủ hầu như không còn dùng. Đây là lời thán phục chứ không phải chê, nên nói hằng ngày đều ổn."}'::jsonb, array['갓벽','레전드','자강두찐'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "In a league of its own"}, {"lang": "🇯🇵 JA", "text": "越えられない壁"}, {"lang": "🇨🇳 ZH", "text": "无法逾越的差距"}, {"lang": "🇻🇳 VI", "text": "Đẳng cấp không với tới"}, {"lang": "🇪🇸 ES", "text": "Nivel inalcanzable"}, {"lang": "🇩🇪 DE", "text": "Unerreichbares Niveau"}]'::jsonb, array[]::text[]),
('297', '엄친아', 'Eom-Chin-A', 'new-slang', '뭐 하나 빠지는 게 없는 완벽한 사람', '{"de": "Der perfekte Mensch, mit dem Mama dich vergleicht", "en": "The flawless overachiever your mom compares you to", "es": "La persona perfecta con la que te comparan", "ja": "何ひとつ欠点のない完璧な人", "vi": "Người hoàn hảo mà mẹ đem ra so sánh"}'::jsonb, '[엄치나]', '[{"type": "명사", "examples": [{"de": "Die Person hat es an die Seoul National University geschafft, ist sportlich und sieht gut aus. Ein echter 엄친아.", "es": "Entró en la Universidad Nacional de Seúl, hace deporte y encima es guapo. Un 엄친아 de manual.", "ja": "あの子ソウル大で運動もできて顔もいいんだって。完全に엄친아じゃん。", "vi": "Bạn ấy đỗ Đại học Quốc gia Seoul, thể thao giỏi, mặt lại đẹp. Đúng chuẩn 엄친아.", "eng": "They got into Seoul National University, they''re athletic, and good-looking too. A total 엄친아.", "kor": "걔 서울대에 운동도 잘하고 얼굴도 잘생겼대. 완전 엄친아네."}, {"de": "Mama hat wieder von Mamas Vorzeigekind angefangen – da war mein Appetit weg.", "es": "Mi madre volvió a sacar el tema del hijo perfecto de su amiga y se me quitó el hambre.", "ja": "母がまた「엄친아」の話を持ち出してきて食欲なくなった。", "vi": "Mẹ lại lôi chuyện ''con nhà người ta'' ra làm mình mất cả ngon miệng.", "eng": "Mom brought up the perfect-kid-next-door thing again and killed my appetite.", "kor": "엄마가 또 엄친아 얘기 꺼내서 밥맛 떨어졌어."}], "definition": "''엄마 친구 아들''의 준말. 공부, 외모, 성격, 집안까지 뭐 하나 빠지는 게 없는 사람을 가리킨다. 원래는 부모가 ''엄마 친구 아들은 이번에 좋은 대학 갔다더라''처럼 남의 집 자식과 비교하던 잔소리에서 나왔는데, 지금은 비교 대상이라는 뜻이 옅어지고 ''완벽한 사람''이라는 칭찬으로 굳었다. 여성은 ''엄친딸''이라고 한다.", "definition_i18n": {"de": "Kurz für ''der Sohn von Mamas Freundin'' — jemand, der alles hat: Noten, Aussehen, Charakter, Elternhaus. Entstand aus dem elterlichen Vergleichsgenörgel (''der Sohn meiner Freundin kam an eine Top-Uni'') und ist heute schlicht ein Kompliment für perfekte Menschen. Weibliche Form: 엄친딸.", "en": "Short for ''my mom''s friend''s son'' — someone with it all: grades, looks, personality, family background. It began as the nagging comparison parents make (''my friend''s son just got into a great university''), and has since settled into a straight compliment for a flawless person. The female version is 엄친딸.", "es": "Abreviatura de ''el hijo de la amiga de mamá'': alguien que lo tiene todo — notas, físico, carácter y familia. Nació del sermón comparativo de los padres (''el hijo de mi amiga entró en una gran universidad'') y hoy es un simple piropo para alguien perfecto. La versión femenina es 엄친딸.", "ja": "「ママの友達の息子」の略。勉強も外見も性格も家柄も、何ひとつ欠けていない人を指す。元は親が「ママの友達の息子は今度いい大学に入ったって」とよその子と比べる小言から生まれたが、今は比較対象という意味は薄れ「完璧な人」という褒め言葉に定着した。女性は엄친딸。", "vi": "Viết tắt của ''con trai bạn của mẹ'' — người có đủ mọi thứ: học giỏi, ngoại hình, tính cách, gia cảnh. Xuất phát từ câu cằn nhằn so sánh của bố mẹ (''con trai bạn mẹ vừa đỗ trường xịn đấy''), nay nghĩa so sánh nhạt đi và thành lời khen cho người hoàn hảo. Dạng nữ là 엄친딸."}}]'::jsonb, '부모가 자식을 다그칠 때 쓰던 ''엄마 친구 아들은 이번에 좋은 대학 갔다더라'' 같은 비교 화법에서 나왔다. 2005년 무렵부터 인터넷에서 줄임말 ''엄친아''로 퍼지며 일반명사처럼 굳었다. 줄임말을 처음 쓴 곳이 어디인지는 출처마다 설명이 갈려 확정되지 않았다.', '{"de": "Aus dem elterlichen Vergleichsspruch: ''der Sohn meiner Freundin kam gerade an eine Top-Uni''. Die Kurzform 엄친아 verbreitete sich ab etwa 2005 online und wurde fast zum Alltagswort. Wer sie zuerst verkürzte, ist umstritten.", "en": "From the comparison parents use to nag their kids: ''my friend''s son just got into a great university.'' The clipped form 엄친아 spread online from around 2005 and hardened into an everyday noun. Which source first clipped it is disputed and unsettled.", "es": "Viene del sermón comparativo de los padres: ''el hijo de mi amiga acaba de entrar en una gran universidad''. La forma corta 엄친아 se difundió en internet desde 2005 y se volvió casi un sustantivo común. Quién la acortó primero está en disputa.", "ja": "親が子どもを叱るときの「ママの友達の息子は今度いい大学に入ったって」という比較の言い回しから生まれた。2005年ごろからネットで略語「엄친아」として広まり、一般名詞のように定着した。誰が最初に略したかは出典によって説が分かれ、確定していない。", "vi": "Bắt nguồn từ câu so sánh bố mẹ hay dùng để rầy con: ''con trai bạn mẹ vừa đỗ trường xịn đấy''. Dạng rút gọn 엄친아 lan trên mạng từ khoảng năm 2005 và thành như một danh từ thông dụng. Ai rút gọn đầu tiên thì các nguồn nói khác nhau, chưa xác định."}'::jsonb, '칭찬이지만 듣는 사람에게는 비교당하는 기분을 줄 수 있어, 본인 앞에서보다 제3자를 두고 말할 때 더 자주 쓴다. 여성에게는 ''엄친딸''을 쓴다.', '{"de": "Ein Kompliment, das aber leicht wie ein Vergleich klingt – deshalb eher über Dritte als direkt zu jemandem. Für Frauen: 엄친딸.", "en": "It''s a compliment, but it can make the listener feel measured against someone, so it''s used more about a third party than to someone''s face. For women, use 엄친딸.", "es": "Es un elogio, pero puede hacer que quien lo oye se sienta comparado, así que se usa más hablando de terceros que a la cara. Para mujeres, 엄친딸.", "ja": "褒め言葉だが、言われた側は比べられている気分になりうるので、本人の前より第三者の話として使うことが多い。女性には엄친딸を使う。", "vi": "Là lời khen, nhưng người nghe dễ thấy mình bị đem ra so sánh, nên thường dùng khi nói về người thứ ba hơn là nói trực diện. Với nữ thì dùng 엄친딸."}'::jsonb, array['갓벽','훈남','갓생'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Mr. Perfect (the kid your mom compares you to)"}, {"lang": "🇯🇵 JA", "text": "ママ友の息子=完璧な人"}, {"lang": "🇨🇳 ZH", "text": "别人家的孩子"}, {"lang": "🇻🇳 VI", "text": "Con nhà người ta"}, {"lang": "🇪🇸 ES", "text": "El hijo perfecto de la amiga de mamá"}, {"lang": "🇩🇪 DE", "text": "Mamas Vorzeigekind"}]'::jsonb, array['엄친딸']),
('298', '안물안궁', 'An-Mul-An-Gung', 'new-slang', '안 물어봤고 안 궁금해', '{"de": "Nicht gefragt, interessiert mich nicht", "en": "Didn''t ask, don''t care", "es": "Ni pregunté ni me interesa", "ja": "聞いてないし興味もない", "vi": "Không hỏi và cũng không quan tâm"}'::jsonb, '[안무란궁]', '[{"type": "감탄사", "examples": [{"de": "Erzählst du das schon wieder? Nicht gefragt, interessiert mich nicht haha", "es": "¿Otra vez esa historia? Ni pregunté ni me interesa jaja", "ja": "またその話?聞いてないし興味ないってwww", "vi": "Lại kể chuyện đó nữa hả? Không hỏi không quan tâm haha", "eng": "You''re telling that story again? Didn''t ask, don''t care lol", "kor": "야 그 얘기 또 해? 안물안궁ㅋㅋ"}, {"de": "Warum fragst du nach meinen Noten? Du sagtest doch, es interessiert dich nicht.", "es": "¿Por qué preguntas por mis notas? Si dijiste que no te interesaba.", "ja": "なんで俺の成績聞くの?興味ないんじゃなかった?", "vi": "Sao lại hỏi điểm của mình? Bảo không quan tâm mà.", "eng": "Why are you asking about my grades? You said you didn''t care.", "kor": "내 성적 왜 물어봐? 안물안궁이라며."}], "definition": "''안 물어봤고 안 궁금하다''의 줄임말. 상대가 묻지도 않은 자기 얘기를 늘어놓거나 남의 일에 참견할 때 말을 끊는 표현이다. 친구끼리는 장난으로 던지지만, 정색하고 쓰면 꽤 무례하게 들린다.", "definition_i18n": {"de": "Kurz für ''habe ich nicht gefragt und interessiert mich nicht''. Bremst jemanden aus, der ungefragt erzählt oder sich einmischt. Unter Freunden ein Scherz, mit ernster Miene ziemlich unhöflich.", "en": "Short for ''I didn''t ask and I''m not curious''. It shuts down someone oversharing or butting into your business. Friends toss it around as a joke, but said with a straight face it comes off pretty rude.", "es": "Abreviatura de ''ni pregunté ni me da curiosidad''. Corta a quien se explaya sin que nadie se lo pida o se mete donde no lo llaman. Entre amigos es una broma; dicho en serio suena bastante grosero.", "ja": "「聞いてないし気にならない」の略。相手が聞かれてもいない自分語りをしたり、他人のことに口を出したときに話を遮る表現。友達同士は冗談で使うが、真顔で言うとかなり失礼に聞こえる。", "vi": "Viết tắt của ''không hỏi và cũng không tò mò''. Dùng để chặn người đang tự kể lể hoặc xen vào chuyện người khác. Bạn bè đùa với nhau thì được, nói mặt nghiêm thì khá mất lịch sự."}}]'::jsonb, '''안 물어봤다''의 준말 ''안물''과 ''안 궁금해''의 준말 ''안궁''을 붙인 말이다. 2010년대 중반 이른바 ''급식체''(중고생 말투)가 유행하면서 함께 퍼졌다.', '{"de": "Eine Verschmelzung von 안물 (''nicht gefragt'') und 안궁 (''nicht neugierig''). Verbreitete sich Mitte der 2010er zusammen mit dem sogenannten 급식체, dem Kurzsprech von Schülerinnen und Schülern.", "en": "A mash-up of 안물 (''didn''t ask'') and 안궁 (''not curious''). It spread in the mid-2010s along with so-called 급식체, the clipped slang style of middle and high schoolers.", "es": "Mezcla de 안물 (''no pregunté'') y 안궁 (''no me da curiosidad''). Se difundió a mediados de los 2010 junto con el llamado 급식체, la jerga recortada de los estudiantes de secundaria.", "ja": "「聞いてない」の略「안물」と「気にならない」の略「안궁」を合わせた語。2010年代半ば、いわゆる「給食体」(中高生の言葉遣い)の流行とともに広まった。", "vi": "Ghép từ 안물 (''không hỏi'') và 안궁 (''không tò mò''). Nó lan rộng giữa thập niên 2010 cùng với 급식체 - lối nói rút gọn của học sinh cấp hai, cấp ba."}'::jsonb, '주로 채팅이나 댓글에서 쓴다. 실제 대화에서 진지하게 쓰면 관계가 상할 수 있어 ''ㅋㅋ'' 같은 웃음 표시를 붙여 장난처럼 쓰는 경우가 많다. 윗사람에게는 절대 쓰지 않는다.', '{"de": "Vor allem in Chats und Kommentaren. Ernst gesagt kann es Freundschaften belasten, deshalb hängt man meist ㅋㅋ (haha) an. Gegenüber Älteren oder Vorgesetzten nie verwenden.", "en": "Mostly in chats and comments. Said seriously in person it can damage a friendship, so people usually soften it with ㅋㅋ (lol). Never use it with someone senior to you.", "es": "Sobre todo en chats y comentarios. Dicho en serio cara a cara puede dañar la amistad, así que se suele suavizar con ㅋㅋ (jaja). Nunca con alguien mayor o superior.", "ja": "主にチャットやコメントで使う。実際の会話で真剣に使うと関係が壊れかねないので、「ㅋㅋ」などの笑いを付けて冗談っぽく使うことが多い。目上の人には絶対に使わない。", "vi": "Chủ yếu dùng trong chat và bình luận. Nói nghiêm túc ngoài đời dễ làm sứt mẻ tình bạn, nên thường kèm ㅋㅋ (haha) cho có vẻ đùa. Tuyệt đối không dùng với người lớn tuổi hơn."}'::jsonb, array['어쩔티비','노잼','팩폭'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Didn''t ask, don''t care"}, {"lang": "🇯🇵 JA", "text": "聞いてないし興味ない"}, {"lang": "🇨🇳 ZH", "text": "没问，也不好奇"}, {"lang": "🇻🇳 VI", "text": "Không hỏi, không quan tâm"}, {"lang": "🇪🇸 ES", "text": "Ni pregunté ni me importa"}, {"lang": "🇩🇪 DE", "text": "Nicht gefragt, egal"}]'::jsonb, array[]::text[]),
('299', '극혐', 'Geuk-Hyeom', 'new-slang', '보기도 싫을 만큼 극도로 싫음', '{"de": "Absolut widerlich", "en": "Beyond gross — a hard pass", "es": "Un asco absoluto", "ja": "見るのも嫌なほど極度に嫌い", "vi": "Ghê tới mức không muốn nhìn"}'::jsonb, '[그켬]', '[{"type": "명사", "examples": [{"de": "Minzschokolade ist absolut widerlich … schmeckt wie Zahnpasta.", "es": "El chocolate con menta me da un asco tremendo… sabe a pasta de dientes.", "ja": "ミントチョコ極嫌…歯磨き粉の味じゃん。", "vi": "Socola bạc hà ghê thật sự… vị y hệt kem đánh răng.", "eng": "Mint choco is a hard pass — it tastes like toothpaste.", "kor": "민트초코 극혐… 치약 맛 나잖아."}, {"de": "Wenn Leute den Gruppenchat mit Fotos zuspammen, finde ich das echt unerträglich.", "es": "Que se pongan a soltar fotos en el grupo me parece insoportable.", "ja": "グループチャットで写真ばらまくの、マジで無理。", "vi": "Cái kiểu spam ảnh trong nhóm chat ghét thật sự.", "eng": "People spamming photos in the group chat is the worst.", "kor": "단톡방에서 사진 막 뿌리는 거 진짜 극혐이야."}], "definition": "''극도로 혐오스럽다''를 두 글자로 줄인 말(극할 극 極 + 싫어할 혐 嫌). 벌레, 음식, 상황처럼 취향에 안 맞는 것에 대해 ''진짜 싫다''를 세게 표현할 때 쓴다. 사람이나 집단을 향해 쓰면 인신공격이 되므로 수위가 세다.", "definition_i18n": {"de": "Zweisilbige Kurzform von ''extrem abstoßend'' (極 extrem + 嫌 verabscheuen). Verstärkt ''das hasse ich wirklich'' bei Insekten, Essen oder Situationen. Auf eine Person oder Gruppe gemünzt wird es ein persönlicher Angriff und wiegt schwer.", "en": "A two-syllable clip of ''extremely repulsive'' (極 extreme + 嫌 loathe). It cranks ''I really hate this'' up a level about bugs, food, or situations you can''t stand. Aimed at a person or group it becomes a personal attack, so it hits hard.", "es": "Contracción de ''extremadamente repulsivo'' (極 extremo + 嫌 aborrecer). Sube el tono de ''esto no lo soporto'' ante bichos, comidas o situaciones. Dirigido a una persona o a un grupo se convierte en ataque personal, así que pesa.", "ja": "「極度に嫌悪する」の2文字略(極+嫌)。虫や食べ物、状況など苦手なものに対して「マジで無理」を強めて言うときに使う。人や集団に向けると人身攻撃になるので強い言葉。", "vi": "Rút gọn hai âm của ''ghê tởm cực độ'' (極 cực + 嫌 ghét). Dùng để nhấn mạnh ''ghét thật sự'' với côn trùng, món ăn hay tình huống khó chịu. Nhắm vào một người hay một nhóm thì thành công kích cá nhân nên khá nặng."}}]'::jsonb, '한자 ''극(極)''과 ''혐(嫌)''을 붙인 인터넷 줄임말이다. 2010년대 초반 디시인사이드 등 커뮤니티에서 ''혐'', ''혐짤'', ''혐주의'' 같은 ''혐'' 계열 표현과 함께 퍼졌다는 설명이 많지만, ''극혐''이라는 말 자체가 처음 어디서 나왔는지는 출처마다 설이 갈려 확정되지 않았다.', '{"de": "Eine Internet-Kurzform aus den sinokoreanischen Zeichen 極 (extrem) und 嫌 (verabscheuen). Viele Quellen datieren die Verbreitung auf die frühen 2010er, zusammen mit der 혐-Familie (혐, 혐짤, 혐주의) in Foren wie DCInside; wo 극혐 selbst zuerst auftauchte, ist umstritten.", "en": "An internet clip fusing the Sino-Korean characters 極 (extreme) and 嫌 (loathe). Many sources place its spread in the early 2010s alongside the 혐 family of terms (혐, 혐짤, 혐주의) on forums like DCInside, but where 극혐 itself first appeared is disputed and unsettled.", "es": "Un acortamiento de internet que une los caracteres 極 (extremo) y 嫌 (aborrecer). Muchas fuentes sitúan su difusión a comienzos de los 2010 junto a la familia 혐 (혐, 혐짤, 혐주의) en foros como DCInside, pero el origen exacto de 극혐 está en disputa.", "ja": "漢字の「極」と「嫌」を合わせたネット略語。2010年代初頭にDCインサイドなどのコミュニティで「혐」「혐짤」「혐주의」といった「嫌」系表現とともに広まったという説明が多いが、「극혐」自体の初出は出典によって説が分かれ確定していない。", "vi": "Một từ rút gọn trên mạng ghép hai chữ Hán 極 (cực) và 嫌 (ghét). Nhiều nguồn cho rằng nó lan rộng đầu thập niên 2010 cùng nhóm từ 혐 (혐, 혐짤, 혐주의) trên các diễn đàn như DCInside, nhưng nơi 극혐 xuất hiện đầu tiên thì các nguồn nói khác nhau, chưa xác định."}'::jsonb, '''극혐이다'', ''이거 극혐''처럼 쓴다. 친한 사이에서 음식이나 취향 이야기를 할 때는 무난하지만, 특정 인물이나 집단에 대고 쓰면 혐오 표현이 되니 주의해야 한다.', '{"de": "Als 극혐이다 oder 이거 극혐. Unter Freunden über Essen oder Geschmack unbedenklich, aber gegen eine bestimmte Person oder Gruppe gerichtet wird es zu Hassrede – Vorsicht.", "en": "Used as 극혐이다 or 이거 극혐. Fine among friends when you''re talking food or taste, but pointed at a specific person or group it becomes hate speech — be careful.", "es": "Se usa como 극혐이다 o 이거 극혐. Entre amigos y hablando de comida o gustos no pasa nada, pero dirigido a una persona o colectivo concreto se convierte en discurso de odio.", "ja": "「극혐이다」「이거 극혐」のように使う。親しい間柄で食べ物や好みの話をするなら問題ないが、特定の人物や集団に向けて使うとヘイト表現になるので注意。", "vi": "Dùng dạng 극혐이다 hay 이거 극혐. Nói chuyện đồ ăn hay sở thích với bạn bè thì ổn, nhưng nhắm vào một người hoặc một nhóm cụ thể thì thành lời lẽ thù ghét, cần cẩn thận."}'::jsonb, array['노잼','헐','소름'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Utterly disgusting / hard pass"}, {"lang": "🇯🇵 JA", "text": "極嫌(超無理)"}, {"lang": "🇨🇳 ZH", "text": "极度厌恶"}, {"lang": "🇻🇳 VI", "text": "Ghê tởm cực độ"}, {"lang": "🇪🇸 ES", "text": "Asco absoluto"}, {"lang": "🇩🇪 DE", "text": "Absolut widerlich"}]'::jsonb, array[]::text[]),
('300', '폼 미쳤다', 'Pom Mi-Chyeot-Da', 'new-slang', '지금 컨디션이 미쳤다, 최고다', '{"de": "Gerade in Wahnsinnsform", "en": "On absolute fire right now", "es": "Está en un momento brutal", "ja": "今の調子がヤバい、絶好調", "vi": "Phong độ đang bùng nổ"}'::jsonb, '[폼 미첟따]', '[{"type": "표현", "examples": [{"de": "Hast du die Bühne gesehen? Die Form war der Wahnsinn.", "es": "¿Viste esa actuación? Estaban en una forma brutal.", "ja": "今回のステージ見た?マジでフォームやばかった。", "vi": "Xem sân khấu lần này chưa? Phong độ đỉnh thật sự.", "eng": "Did you see that stage? Their form was absolutely insane.", "kor": "이번 무대 봤어? 진짜 폼 미쳤더라."}, {"de": "Dieses Album ist der Wahnsinn – kein einziger Song zum Überspringen.", "es": "Este álbum está a otro nivel, no hay una sola canción para saltarse.", "ja": "今回のアルバム、フォーム미쳤다。捨て曲がない。", "vi": "Album lần này đỉnh thật, không có bài nào phải bỏ qua.", "eng": "This album is on fire — not a single skip.", "kor": "이번 앨범 폼 미쳤다, 버릴 곡이 없어."}], "definition": "''폼(form, 컨디션·기량)이 미쳤다''는 뜻으로, 누군가의 상태나 퍼포먼스가 최고조일 때 쓰는 최상급 칭찬. 원래 축구 같은 스포츠에서 선수 컨디션을 말하던 표현인데, 지금은 아이돌 무대·요리·옷차림까지 일상 전반으로 넓어졌다.", "definition_i18n": {"de": "''Die Form ist verrückt'' — höchstes Lob für jemanden in Bestform. Kommt aus dem Sport (vor allem Fußball) und gilt heute für Idol-Bühnen, Kochen, Outfits, alles.", "en": "''Their form is insane'' — top-tier praise for someone at the peak of their game. It started as sports talk (mostly football) about a player''s condition and has since spread to idol stages, cooking, outfits, anything.", "es": "''Su forma está de locos'': el elogio máximo para alguien en su mejor momento. Nació en el fútbol para hablar del estado de un jugador y hoy se aplica a escenarios de ídolos, cocina, outfits, lo que sea.", "ja": "「フォーム(調子・実力)がヤバい」という意味で、誰かの状態やパフォーマンスが絶好調のときに使う最上級の褒め言葉。元はサッカーなどで選手のコンディションを指した表現だが、今はアイドルのステージや料理、服装まで日常全般に広がった。", "vi": "''Phong độ điên rồ'' — lời khen ở mức cao nhất cho ai đó đang ở đỉnh cao. Vốn là cách nói trong thể thao (chủ yếu bóng đá) về thể trạng cầu thủ, nay lan sang sân khấu idol, nấu ăn, cách ăn mặc."}}]'::jsonb, '축구 해설가 이주헌의 별명 ''추멘''에서 나온 ''추멘 폼 미쳤다(줄여서 추폼미)''가 2018년 인터넷 방송에서 밈이 되면서, 별명을 뗀 ''폼 미쳤다''만 남아 일반 표현으로 퍼졌다.', '{"de": "Aus ''추멘 폼 미쳤다'' (kurz 추폼미), einem Meme von 2018 aus Internetsendungen rund um den Spitznamen 추멘 des Fußballkommentators Lee Ju-heon. Der Spitzname fiel weg, nur ''폼 미쳤다'' setzte sich als allgemeine Wendung durch.", "en": "From ''추멘 폼 미쳤다'' (shortened to 추폼미), a 2018 internet-broadcast meme built on football commentator Lee Ju-heon''s nickname 추멘. The nickname was dropped and only ''폼 미쳤다'' spread as a general phrase.", "es": "Viene de ''추멘 폼 미쳤다'' (abreviado 추폼미), un meme de 2018 nacido en emisiones por internet a partir del apodo 추멘 del comentarista de fútbol Lee Ju-heon. Se cayó el apodo y solo ''폼 미쳤다'' se extendió como expresión general.", "ja": "サッカー解説者イ・ジュホンのあだ名「チュメン」から生まれた「チュメン フォームがヤバい(略してチュポンミ)」が2018年のネット放送でミーム化し、あだ名が取れた「폼 미쳤다」だけが一般表現として広まった。", "vi": "Từ ''추멘 폼 미쳤다'' (rút gọn là 추폼미), một meme năm 2018 trên các buổi phát sóng internet dựa trên biệt danh 추멘 của bình luận viên bóng đá Lee Ju-heon. Biệt danh rụng mất, chỉ còn ''폼 미쳤다'' lan ra thành cách nói chung."}'::jsonb, '칭찬 전용 표현이다. 사람뿐 아니라 앨범·경기·요리 같은 결과물에도 쓴다. 반대로 상태가 떨어졌을 때는 ''폼 떨어졌다''라고 한다.', '{"de": "Nur als Lob. Gilt für Menschen wie für Dinge – Alben, Spiele, Gerichte. Das Gegenteil bei einem Formtief: 폼 떨어졌다.", "en": "Praise only. Works for people and for things — albums, matches, dishes. The opposite, for someone slumping, is 폼 떨어졌다.", "es": "Solo para elogiar. Vale para personas y para cosas: álbumes, partidos, platos. Lo contrario, cuando alguien baja de nivel, es 폼 떨어졌다.", "ja": "褒め言葉専用。人だけでなくアルバムや試合、料理といった成果物にも使う。逆に調子が落ちたときは「폼 떨어졌다」と言う。", "vi": "Chỉ dùng để khen. Áp dụng cho cả người lẫn sản phẩm: album, trận đấu, món ăn. Ngược lại, khi phong độ đi xuống thì nói 폼 떨어졌다."}'::jsonb, array['개미쳤다','레전드','찐텐'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "On fire / in peak form"}, {"lang": "🇯🇵 JA", "text": "フォームがヤバい"}, {"lang": "🇨🇳 ZH", "text": "状态神了"}, {"lang": "🇻🇳 VI", "text": "Phong độ đỉnh cao"}, {"lang": "🇪🇸 ES", "text": "En una racha brutal"}, {"lang": "🇩🇪 DE", "text": "In Wahnsinnsform"}]'::jsonb, array[]::text[]),
('301', '오히려 좋아', 'O-Hi-Ryeo Jo-A', 'new-slang', '망한 김에 오히려 잘됐다', '{"de": "Im Gegenteil, sogar besser", "en": "Actually, this is better", "es": "En realidad, mejor así", "ja": "むしろ好都合", "vi": "Ngược lại, thế lại hay"}'::jsonb, '[오히려 조:아]', '[{"type": "표현", "examples": [{"de": "Das Picknick fällt wegen Regen aus. Dann ruhe ich mich zu Hause aus – im Gegenteil, sogar besser.", "es": "Se canceló el pícnic por la lluvia. Puedo descansar en casa: en realidad, mejor así.", "ja": "雨で遠足中止だって。家で休めるし、むしろ好都合。", "vi": "Trời mưa nên chuyến dã ngoại bị hủy. Ở nhà nghỉ cũng được mà, ngược lại thế lại hay.", "eng": "The picnic got cancelled because of rain. Now I can rest at home — actually, this is better.", "kor": "비 와서 소풍 취소됐네. 집에서 쉬면 되지, 오히려 좋아."}, {"de": "Ich habe den Bus verpasst, aber der nächste war leer und ich hatte einen Sitzplatz. Im Gegenteil, besser so haha", "es": "Perdí el autobús, pero el siguiente venía vacío y me senté. Mejor así jaja", "ja": "バス逃したけど次の便がガラガラで座れた。むしろ好都合www", "vi": "Lỡ xe buýt nhưng chuyến sau trống trơn nên được ngồi. Thế lại hay haha", "eng": "I missed my bus, but the next one was empty and I got a seat. Actually a win lol", "kor": "버스 놓쳤는데 다음 차가 텅 비어서 앉아 왔어. 오히려 좋아ㅋㅋ"}], "definition": "누가 봐도 안 좋은 일이 벌어졌을 때 ''오히려 이게 더 낫다''며 상황을 뒤집는 말. 진짜로 긍정적인 면을 찾을 때도 쓰고, 뻔히 손해인 걸 알면서 웃자고 하는 정신승리로도 쓴다.", "definition_i18n": {"de": "Sagt man, wenn etwas offensichtlich schiefgelaufen ist, und dreht es um: ''so ist es sogar besser''. Mal ehrliche Suche nach dem Guten, mal bewusst ironische Schönrederei zum Lachen.", "en": "Said when something has clearly gone wrong, flipping it into ''actually, this works out better''. It can be genuine silver-lining hunting, or open, self-aware copium played for laughs.", "es": "Se dice cuando algo ha salido claramente mal, para darle la vuelta: ''en realidad así es mejor''. Puede ser una búsqueda sincera del lado bueno o puro consuelo irónico para hacer reír.", "ja": "誰が見ても悪いことが起きたときに「むしろこっちの方がいい」と状況をひっくり返す言葉。本当に良い面を探すときにも、損だと分かっていて笑いを取る精神勝利にも使う。", "vi": "Nói khi chuyện rõ ràng đã hỏng, lật ngược thành ''thế này lại hay hơn''. Có thể là thật lòng tìm mặt tích cực, cũng có thể là tự an ủi cho vui dù biết rõ mình thiệt."}}]'::jsonb, '어원은 확정되지 않았고 여러 설이 있다. 2010년대 중후반 아프리카TV 스타크래프트 방송의 관전·해설 문화에서 나왔다는 설, 게임 방송 시청자들 사이에서 번졌다는 설 등이 병존한다. 다만 대중적으로 퍼진 계기로는 유튜버 침착맨이 자주 쓴 것이 공통적으로 꼽힌다.', '{"de": "Die Herkunft ist ungeklärt, mehrere Theorien bestehen nebeneinander: Entstehung aus der Mitschau- und Kommentarkultur der AfreecaTV-StarCraft-Übertragungen der späten 2010er, oder Verbreitung unter Gaming-Stream-Zuschauern. Einig sind sich die Quellen, dass YouTuber Chimchakman es durch häufigen Gebrauch populär machte.", "en": "The origin is unsettled and several theories coexist: that it came out of the co-watching and commentary culture of AfreecaTV StarCraft broadcasts in the late 2010s, or that it spread among game-stream viewers. What sources agree on is that YouTuber Chimchakman''s frequent use is what took it mainstream.", "es": "El origen no está fijado y conviven varias teorías: que surgió de la cultura de ver y comentar partidas de StarCraft en AfreecaTV a finales de los 2010, o que se extendió entre espectadores de streams de videojuegos. En lo que coinciden las fuentes es en que el youtuber Chimchakman lo popularizó al usarlo constantemente.", "ja": "語源は確定しておらず諸説ある。2010年代中後半のアフリカTVスタークラフト放送の観戦・解説文化から生まれたという説、ゲーム配信の視聴者間で広がったという説などが並立する。ただし大衆化のきっかけとしては、YouTuberチムチャンメンが頻繁に使ったことが共通して挙げられる。", "vi": "Nguồn gốc chưa được xác định, tồn tại nhiều giả thuyết: rằng nó ra đời từ văn hóa xem và bình luận các trận StarCraft trên AfreecaTV cuối thập niên 2010, hoặc lan giữa khán giả stream game. Điều các nguồn đồng ý là YouTuber Chimchakman dùng nhiều khiến nó phổ biến."}'::jsonb, '안 좋은 소식 뒤에 붙여 분위기를 푸는 데 쓴다. 정색하고 위로하기보다 가볍게 넘길 때 어울리며, 남의 큰 불행에 대고 쓰면 비꼬는 것처럼 들리니 조심.', '{"de": "Hängt man an schlechte Nachrichten, um die Stimmung zu lockern. Passt eher zum Achselzucken als zum ernsten Trost – bei echtem Unglück anderer kann es sarkastisch klingen.", "en": "Tacked onto bad news to lighten the mood. It fits a shrug better than a serious consolation — used about someone else''s real misfortune it can sound sarcastic, so be careful.", "es": "Se añade tras una mala noticia para aligerar el ambiente. Encaja mejor con un ''bueno, da igual'' que con un consuelo serio; ante la desgracia real de otra persona puede sonar sarcástico.", "ja": "悪い知らせの後に付けて空気を和らげるのに使う。真剣な慰めより軽く流すときに合い、他人の大きな不幸に対して使うと皮肉に聞こえるので注意。", "vi": "Thêm vào sau tin xấu để làm nhẹ không khí. Hợp với kiểu cho qua hơn là an ủi nghiêm túc; dùng trước nỗi bất hạnh lớn của người khác dễ nghe như mỉa mai, nên cẩn thận."}'::jsonb, array['럭키비키','갓생','사이다'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Actually, this is better"}, {"lang": "🇯🇵 JA", "text": "むしろ好都合"}, {"lang": "🇨🇳 ZH", "text": "反而更好"}, {"lang": "🇻🇳 VI", "text": "Ngược lại lại hay"}, {"lang": "🇪🇸 ES", "text": "En realidad, mejor así"}, {"lang": "🇩🇪 DE", "text": "Im Gegenteil, besser so"}]'::jsonb, array[]::text[]),
('302', '이븐하게', 'I-Beun-Ha-Ge', 'new-slang', '골고루, 균일하게', '{"de": "Gleichmäßig", "en": "Evenly, uniformly", "es": "De forma uniforme", "ja": "均一に、まんべんなく", "vi": "Đều tay, đồng đều"}'::jsonb, null, '[{"type": "부사", "examples": [{"de": "Brate das Fleisch gleichmäßig – eine Seite ist verbrannt.", "es": "Cocina la carne de forma uniforme, un lado está quemado.", "ja": "肉ちょっと均一に焼いてよ、片面だけ焦げてるじゃん。", "vi": "Nướng thịt cho đều tay đi, một mặt cháy rồi kìa.", "eng": "Cook the meat evenly — one side is burnt.", "kor": "고기 좀 이븐하게 구워봐, 한쪽만 탔잖아."}, {"de": "Ohne Sonnencreme ist meine Bräune ungleichmäßig geworden haha", "es": "No me puse protector y el bronceado me quedó irregular jaja", "ja": "日焼け止め塗らなかったから焼けムラができたwww", "vi": "Không bôi kem chống nắng nên da rám nắng không đều haha", "eng": "I skipped the sunscreen so my tan came out uneven lol", "kor": "선크림 안 발라서 태닝이 이븐하게 안 됐어ㅋㅋ"}], "definition": "영어 even(고른)에 한국어 어미 ''-하게''를 붙인 한영 혼용어로 ''골고루, 균일하게''라는 뜻. 넷플릭스 요리 예능 <흑백요리사>(2024)의 심사평 ''이븐하게 익지 않았어요''가 밈이 되면서, 요리 밖에서도 장난스럽게 쓰인다.", "definition_i18n": {"de": "Englisch ''even'' plus die koreanische Adverbendung -하게: ''gleichmäßig''. Der Jurysatz ''이븐하게 익지 않았어요'' (''nicht gleichmäßig gegart'') aus der Netflix-Kochshow Culinary Class Wars (2024) machte daraus ein Meme, das heute auch weit außerhalb der Küche scherzhaft benutzt wird.", "en": "English ''even'' plus the Korean adverb ending -하게, meaning ''evenly, uniformly''. The judging line ''이븐하게 익지 않았어요'' (''it isn''t cooked evenly'') from the Netflix cooking show Culinary Class Wars (2024) turned it into a meme now used jokingly well outside the kitchen.", "es": "Del inglés ''even'' más la terminación adverbial coreana -하게: ''de manera uniforme''. La frase del jurado ''이븐하게 익지 않았어요'' (''no está cocido de forma uniforme''), del programa de Netflix Culinary Class Wars (2024), la convirtió en meme y hoy se usa en broma mucho más allá de la cocina.", "ja": "英語のeven(均等な)に韓国語の語尾「-하게」を付けた韓英混用語で「均一に、まんべんなく」の意味。Netflixの料理番組『黒白料理師(흑백요리사)』(2024)の審査コメント「이븐하게 익지 않았어요(均一に火が通っていません)」がミーム化し、料理以外でも冗談めかして使われる。", "vi": "Từ ''even'' tiếng Anh ghép với đuôi trạng từ -하게 của tiếng Hàn, nghĩa là ''đều, đồng đều''. Câu nhận xét ''이븐하게 익지 않았어요'' (''chưa chín đều'') trong show nấu ăn Culinary Class Wars (2024) của Netflix đã biến nó thành meme, nay dùng đùa cả ngoài chuyện bếp núc."}}]'::jsonb, '넷플릭스 요리 예능 <흑백요리사: 요리 계급 전쟁>(2024)의 심사평 ''이븐하게 익지 않았어요''에서 퍼졌다. 어느 심사위원의 발언인지는 출처마다 표기가 갈리거나 아예 언급되지 않아 확정하지 않는다.', '{"de": "Verbreitet durch den Jurysatz ''이븐하게 익지 않았어요'' aus der Netflix-Kochshow Culinary Class Wars (2024). Welches Jurymitglied ihn sagte, wird nicht genannt oder unterschiedlich angegeben und bleibt offen.", "en": "It spread from the judging line ''이븐하게 익지 않았어요'' (''it isn''t cooked evenly'') on the Netflix cooking show Culinary Class Wars (2024). Which judge said it is either unstated or inconsistent across sources, so it is left unsettled.", "es": "Se difundió a partir de la frase del jurado ''이븐하게 익지 않았어요'' en el programa de Netflix Culinary Class Wars (2024). Qué juez la dijo no se indica o varía según la fuente, así que queda sin determinar.", "ja": "Netflixの料理番組『黒白料理師:料理階級戦争』(2024)の審査コメント「이븐하게 익지 않았어요」から広まった。どの審査員の発言かは出典によって記載が異なるか言及がなく、確定しない。", "vi": "Lan ra từ câu nhận xét ''이븐하게 익지 않았어요'' trong show nấu ăn Culinary Class Wars (2024) của Netflix. Vị giám khảo nào nói câu đó thì các nguồn hoặc không nêu hoặc nói khác nhau, nên không khẳng định."}'::jsonb, '요리 이야기에서는 진짜 ''골고루''라는 뜻으로 쓰고, 그 밖에는 밈으로 아무 데나 붙여 웃음을 노린다(예: ''태닝이 이븐하게 안 됐네''). 표준어가 아닌 한영 혼용 유행어라 공식 문서에는 쓰지 않는다.', '{"de": "Beim Kochen meint es wirklich ''gleichmäßig''; sonst hängt man es überall dran, um Lacher zu ernten (''meine Bräune ist nicht gleichmäßig geworden''). Es ist eine koreanisch-englische Mischform, kein Standardkoreanisch – in formellen Texten also vermeiden.", "en": "In cooking talk it genuinely means ''evenly''; everywhere else it''s slapped on for laughs (''my tan didn''t come out evenly''). It''s a Korean-English hybrid, not standard Korean, so keep it out of formal writing.", "es": "Hablando de cocina significa de verdad ''uniformemente''; en cualquier otro contexto se pega por la gracia (''el bronceado no me quedó uniforme''). Es un híbrido coreano-inglés, no coreano estándar, así que fuera de textos formales.", "ja": "料理の話では本当に「均一に」の意味で使い、それ以外はミームとしてどこにでも付けて笑いを取る(例:「日焼けが均一にならなかった」)。標準語ではない韓英混用の流行語なので、公式文書には使わない。", "vi": "Trong chuyện bếp núc nó thật sự nghĩa là ''đều''; ngoài ra thì gắn vào đâu cũng được cho vui (''da rám nắng không đều''). Đây là từ lai Hàn - Anh, không phải tiếng Hàn chuẩn, nên đừng dùng trong văn bản trang trọng."}'::jsonb, array['밈','국룰','재질'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Evenly / uniformly"}, {"lang": "🇯🇵 JA", "text": "均一に"}, {"lang": "🇨🇳 ZH", "text": "均匀地"}, {"lang": "🇻🇳 VI", "text": "Đều, đồng đều"}, {"lang": "🇪🇸 ES", "text": "De forma uniforme"}, {"lang": "🇩🇪 DE", "text": "Gleichmäßig"}]'::jsonb, array[]::text[]),
('303', '실화냐', 'Sil-Hwa-Nya', 'new-slang', '이게 진짜 실제 상황이야?', '{"de": "Ist das gerade wirklich echt?", "en": "Is this for real right now?", "es": "¿Esto va en serio?", "ja": "これマジで実話?", "vi": "Cái này là thật hả?"}'::jsonb, null, '[{"type": "표현", "examples": [{"de": "Diese Qualität zu dem Preis? Ist das echt?", "es": "¿Esta calidad a este precio? ¿Va en serio?", "ja": "この値段でこのクオリティ?実話?", "vi": "Chất lượng này mà giá này? Thật hả?", "eng": "This quality at this price? Is this for real?", "kor": "이 가격에 이 퀄리티? 실화냐?"}, {"de": "Die Prüfung ist morgen? Das kann nicht echt sein …", "es": "¿El examen es mañana? No puede ser real…", "ja": "明日が試験?これ実話…?", "vi": "Mai thi rồi á? Không thể là thật được…", "eng": "The exam is tomorrow? This can''t be real…", "kor": "내일이 시험이라고? 이거 실화냐…"}], "definition": "''이거 실화냐?''의 준말로, 믿기 힘든 일이나 어이없는 상황을 봤을 때 ''이게 진짜야?''라고 되묻는 말. 감탄할 때도, 황당할 때도 똑같이 쓴다. 어느 쪽으로 검색해도 같은 항목이다.", "definition_i18n": {"de": "Kurz für ''이거 실화냐?'' (''ist das eine wahre Geschichte?'') — die Reflexfrage bei etwas Unglaublichem. Funktioniert für Staunen wie für Fassungslosigkeit. Beide Formen führen zu diesem einen Eintrag.", "en": "Short for ''이거 실화냐?'' (''is this a true story?'') — the reflex question when something is too wild to believe. It works the same for awe and for disbelief. Either form leads to this one entry.", "es": "Abreviatura de ''이거 실화냐?'' (''¿esto es una historia real?''): la pregunta refleja ante algo increíble. Vale igual para el asombro y para la incredulidad. Ambas formas llevan a esta misma entrada.", "ja": "「이거 실화냐?(これ実話?)」の略で、信じがたい出来事やあきれる状況を見たときに「これマジ?」と聞き返す言葉。感嘆にも呆れにも同じように使う。どちらで検索しても同じ項目。", "vi": "Rút gọn của ''이거 실화냐?'' (''chuyện này có thật không?'') — câu hỏi bật ra khi thấy điều quá khó tin. Dùng như nhau cho cả kinh ngạc lẫn ngán ngẩm. Tìm theo dạng nào cũng ra mục này."}}]'::jsonb, '다음팟(TV팟) 시청자들이 아무 영상에나 ''이거 실화냐?''라고 되묻던 어그로성 드립에서 시작해, 아프리카TV BJ 겸 유튜버 보겸 등이 즐겨 쓰면서 퍼진 것으로 알려져 있다. 2017년에는 네티즌이 뽑은 그해 유행어 3위에 오를 만큼 대중화됐다.', '{"de": "Angeblich begann es als provokanter Running Gag unter Zuschauern von Daum Pot (TV Pot), die zu jedem beliebigen Video fragten ''ist das echt?'', und verbreitete sich über Streamer wie den AfreecaTV-BJ und YouTuber Bogyeom. 2017 landete es in einer Netzumfrage auf Platz drei der Sprüche des Jahres.", "en": "It reportedly started as a troll-ish running gag among Daum Pot (TV Pot) viewers who asked ''is this a true story?'' about any video at all, then spread through streamers like AfreecaTV BJ and YouTuber Bogyeom. By 2017 it was mainstream enough to place third in a netizen poll of the year''s catchphrases.", "es": "Al parecer empezó como una coña provocadora entre espectadores de Daum Pot (TV Pot), que preguntaban ''¿esto es real?'' ante cualquier vídeo, y se extendió gracias a streamers como el BJ y youtuber Bogyeom. En 2017 quedó tercera en una encuesta de internautas sobre las frases del año.", "ja": "ダウムパッ(TVパッ)の視聴者がどんな動画にも「これ実話?」と聞き返す煽り気味のネタから始まり、アフリカTVのBJ兼YouTuberボギョムらが好んで使って広まったとされる。2017年にはネット民が選ぶその年の流行語3位に入るほど大衆化した。", "vi": "Được cho là bắt đầu như một trò trêu của khán giả Daum Pot (TV Pot), hỏi ''cái này thật hả?'' với bất kỳ video nào, rồi lan rộng nhờ các streamer như BJ kiêm YouTuber Bogyeom. Năm 2017 nó phổ biến tới mức đứng thứ ba trong bình chọn câu cửa miệng của năm."}'::jsonb, '감탄과 어이없음 양쪽에 다 쓴다. ''실화냐'', ''이거 실화냐'', ''실화임?''처럼 변형해 쓰며, 어느 쪽으로 검색해도 같은 말이다. 반말이라 친구 사이에서 쓴다.', '{"de": "Für Staunen wie für Fassungslosigkeit. Varianten: 실화냐, 이거 실화냐, 실화임? – alles dasselbe. Es ist saloppe Sprache, also nur unter Freunden.", "en": "Used for both awe and exasperation. Varies as 실화냐, 이거 실화냐, 실화임? — all the same expression. It''s casual speech, so keep it among friends.", "es": "Sirve tanto para el asombro como para la exasperación. Varía como 실화냐, 이거 실화냐, 실화임?, todas la misma expresión. Es habla informal, así que resérvala para amigos.", "ja": "感嘆にも呆れにも使う。「실화냐」「이거 실화냐」「실화임?」と形を変えて使うが、どれも同じ表現。タメ口なので友達同士で使う。", "vi": "Dùng cho cả kinh ngạc lẫn bực bội. Biến thể 실화냐, 이거 실화냐, 실화임? đều là một. Đây là lối nói suồng sã nên chỉ dùng với bạn bè."}'::jsonb, array['이왜진','헐','소름'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Is this for real?"}, {"lang": "🇯🇵 JA", "text": "これ実話?"}, {"lang": "🇨🇳 ZH", "text": "这是真的吗"}, {"lang": "🇻🇳 VI", "text": "Thật hả?"}, {"lang": "🇪🇸 ES", "text": "¿Esto va en serio?"}, {"lang": "🇩🇪 DE", "text": "Ist das echt?"}]'::jsonb, array['이거 실화냐','실화임?']),
('304', '나락', 'Na-Rak', 'new-slang', '한순간에 바닥으로 추락함', '{"de": "Ein Absturz ins Bodenlose", "en": "A career-ending nosedive", "es": "Caída en picado hasta lo más bajo", "ja": "一瞬で奈落まで転落すること", "vi": "Rơi thẳng xuống đáy trong tích tắc"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Dieser eine Satz hat das ganze Image abstürzen lassen.", "es": "Con ese comentario su imagen se fue al abismo.", "ja": "あの一言でイメージ完全に奈落だよ。", "vi": "Chỉ một câu đó thôi mà hình ảnh rơi thẳng xuống đáy.", "eng": "That one comment sent their whole image straight down the drain.", "kor": "그 말 한마디로 이미지 나락 갔잖아."}, {"de": "Ich habe die Prüfung verhauen und meine Laune ist im freien Fall.", "es": "Suspendí el examen y mi ánimo va en caída libre.", "ja": "試験やらかしてメンタル奈落行き中。", "vi": "Thi hỏng rồi, tinh thần đang rơi tự do.", "eng": "I bombed the exam and my mental state is in free fall.", "kor": "시험 망쳐서 내 멘탈 나락 가는 중."}], "definition": "원래 불교에서 지옥을 뜻하는 말(奈落)인데, 인터넷에서는 실수나 논란 하나로 평판·이미지가 한순간에 무너지는 것을 가리킨다. 주로 ''나락 갔다'', ''나락 간다''처럼 쓴다.", "definition_i18n": {"de": "Ursprünglich das buddhistische Wort für Hölle (奈落); online beschreibt es einen Ruf, der wegen eines Fehlers oder Skandals schlagartig zusammenbricht. Meist als 나락 갔다 oder 나락 간다.", "en": "Originally the Buddhist word for hell (奈落); online it describes a reputation or image collapsing in an instant over one slip or scandal. Usually said as 나락 갔다 or 나락 간다.", "es": "Originalmente la palabra budista para el infierno (奈落); en internet describe una reputación que se derrumba de golpe por un error o un escándalo. Se usa como 나락 갔다 o 나락 간다.", "ja": "元は仏教で地獄を意味する語(奈落)だが、ネットではミスや炎上ひとつで評判やイメージが一瞬で崩れることを指す。主に「나락 갔다」「나락 간다」の形で使う。", "vi": "Vốn là từ Phật giáo chỉ địa ngục (奈落); trên mạng nó chỉ việc danh tiếng, hình ảnh sụp đổ trong tích tắc chỉ vì một sai lầm hay bê bối. Thường nói 나락 갔다 hoặc 나락 간다."}}]'::jsonb, '불교 용어 ''나락(奈落)''에서 왔다. 인터넷 유행어로 굳은 경위로는 2020년 전후 아프리카TV 방송 문화에서 시작됐다는 설이 널리 퍼져 있다(스트리머끼리의 대화에서 나온 말이 별명과 이른바 ''나락송''으로 밈화됐다는 설). 다만 최초 발화자와 시점은 출처마다 설명이 갈려 확정되지 않았다.', '{"de": "Vom buddhistischen Begriff 나락 (奈落). Verbreitet ist die Darstellung, dass es sich um 2020 in der AfreecaTV-Streaming-Kultur als Slang verfestigte — eine Bemerkung zwischen Streamern wurde zum Spitznamen und dann zum Meme-Song 나락송 —, wer es zuerst sagte und wann, ist jedoch quellenabhängig und ungeklärt.", "en": "From the Buddhist term 나락 (奈落). The widely repeated account is that it hardened into slang around 2020 in AfreecaTV streaming culture — a remark between streamers became a nickname and then the so-called 나락송 meme song — but who said it first, and when, differs between sources and is unsettled.", "es": "Del término budista 나락 (奈落). La versión más repetida es que se fijó como jerga hacia 2020 en la cultura de streaming de AfreecaTV — un comentario entre streamers se convirtió en apodo y luego en la canción-meme 나락송 —, pero quién lo dijo primero y cuándo varía según la fuente.", "ja": "仏教用語の「奈落」から来ている。ネット流行語として定着した経緯は、2020年前後のアフリカTV配信文化から始まったという説が広く知られる(配信者同士の会話で出た言葉があだ名や「나락송」というミーム曲になったという説)。ただし最初の発話者や時期は出典によって異なり確定していない。", "vi": "Từ thuật ngữ Phật giáo 나락 (奈落). Cách giải thích phổ biến là nó thành tiếng lóng quanh năm 2020 trong văn hóa stream AfreecaTV — một câu nói giữa các streamer thành biệt danh rồi thành bài meme 나락송 — nhưng ai nói đầu tiên và khi nào thì các nguồn khác nhau, chưa xác định."}'::jsonb, '''나락 갔다'', ''나락 가는 중'', ''나락 보내다''처럼 쓴다. 연예인·스트리머의 논란 이야기에 자주 나오고, 친구끼리 사소한 실수를 두고 장난으로도 쓴다. 당사자에게 직접 쓰면 조롱이 되니 주의.', '{"de": "Als 나락 갔다, 나락 가는 중, 나락 보내다. Taucht ständig bei Promi- und Streamer-Skandalen auf; unter Freunden auch scherzhaft für kleine Patzer. Direkt gesagt ist es Spott – Vorsicht.", "en": "Used as 나락 갔다, 나락 가는 중, 나락 보내다. It shows up constantly in talk about celebrity and streamer scandals, and friends use it jokingly about small slip-ups. Said to someone''s face it''s mockery, so be careful.", "es": "Se usa como 나락 갔다, 나락 가는 중, 나락 보내다. Aparece sin parar al hablar de escándalos de famosos y streamers, y entre amigos para bromear sobre pequeños fallos. Dicho a la cara es burla, así que cuidado.", "ja": "「나락 갔다」「나락 가는 중」「나락 보내다」のように使う。芸能人や配信者の炎上話に頻出し、友達同士では小さなミスをからかうのにも使う。本人に直接言うと嘲笑になるので注意。", "vi": "Dùng dạng 나락 갔다, 나락 가는 중, 나락 보내다. Xuất hiện liên tục khi bàn về bê bối của người nổi tiếng và streamer, bạn bè cũng dùng để đùa về những lỗi nhỏ. Nói thẳng vào mặt ai đó thì thành chế giễu, cần cẩn thận."}'::jsonb, array['현타','손절','억까'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "To fall from grace / to tank"}, {"lang": "🇯🇵 JA", "text": "奈落に落ちる"}, {"lang": "🇨🇳 ZH", "text": "跌入谷底"}, {"lang": "🇻🇳 VI", "text": "Rơi xuống đáy"}, {"lang": "🇪🇸 ES", "text": "Caer en desgracia"}, {"lang": "🇩🇪 DE", "text": "Absturz ins Bodenlose"}]'::jsonb, array[]::text[]);

commit;

